const request = require('supertest');
const app = require('../app');

describe('Security Headers', () => {
  it('should have Helmet headers', async () => {
    const res = await request(app).get('/health');

    expect(res.headers).toHaveProperty('x-dns-prefetch-control', 'off');
    expect(res.headers).toHaveProperty('x-frame-options', 'SAMEORIGIN');
    expect(res.headers).toHaveProperty('x-content-type-options', 'nosniff');
    expect(res.headers).toHaveProperty('x-download-options', 'noopen');
    expect(res.headers).toHaveProperty('x-permitted-cross-domain-policies', 'none');
    expect(res.headers).toHaveProperty('strict-transport-security');
    expect(res.headers).toHaveProperty('content-security-policy');
  });
});

describe('Rate Limiting', () => {
  it('should limit repeated requests', async () => {
    // Make 101 requests within the window
    for (let i = 0; i < 101; i++) {
      await request(app).get('/health');
    }

    // The 102nd request should be rate limited
    const res = await request(app).get('/health');
    expect(res.status).toBe(429);
    expect(res.text).toMatch(/too many requests/i);
  });
});

